#include <stdio.h>
int main(void) {
    FILE *input = fopen("sample.txt", "r");
    if (input == NULL) {
        printf("open failed\n");
        return 1;
    }
    int ch = fgetc(input);
    while (ch != EOF) {
        putchar(ch);
        ch = fgetc(input);
    }
    int failed = ferror(input);
    if (fclose(input) == EOF) return 1;
    return failed ? 1 : 0;
}

#include <stdio.h>
int main(void) {
    int guess = 1;
    while (guess <= 5) {
        printf("guess=%d\n", guess);
        int response = getchar();
        if (response == EOF) break;
        int rest = response;
        while (rest != EOF && rest != '\n') rest = getchar();
        if (response == 'y') {
            printf("matched\n");
            break;
        } else if (response == 'n') {
            guess++;
        } else {
            printf("invalid\n");
        }
        if (rest == EOF) break;
    }
    return 0;
}

#include <stdio.h>
void draw(char symbol, int rows, int columns);
int main(void) {
    int first = getchar();
    int rows = 0, columns = 0;
    if (first == EOF) return 1;
    if (scanf("%d", &rows) != 1) return 1;
    if (scanf("%d", &columns) != 1) return 1;
    if (rows < 1 || rows > 3 || columns < 1 || columns > 3) return 1;
    draw((char)first, rows, columns);
    int next = getchar();
    printf("next-code=%d\n", next);
    return 0;
}
void draw(char symbol, int rows, int columns) {
    for (int row = 0; row < rows; row++) {
        for (int col = 0; col < columns; col++) putchar(symbol);
        putchar('\n');
    }
}

#include <stdio.h>
void emit_rows(char symbol, int rows, int columns);
int main(void) {
    int first = getchar();
    while (first != EOF && first != '\n') {
        int rows = 0, columns = 0;
        if (scanf("%d", &rows) != 1) break;
        if (scanf("%d", &columns) != 1) break;
        if (rows < 1 || rows > 3 || columns < 1 || columns > 3) return 1;
        emit_rows((char)first, rows, columns);
        int rest = getchar();
        while (rest != EOF && rest != '\n') rest = getchar();
        if (rest == EOF) break;
        first = getchar();
    }
    return 0;
}
void emit_rows(char symbol, int rows, int columns) {
    for (int line = 0; line < rows; line++) {
        for (int cell = 0; cell < columns; cell++) putchar(symbol);
        putchar('\n');
    }
}

#include <stdio.h>
int checked_int(int *target);
double square_range(int low, int high);
int main(void) {
    int low = 0, high = 0;
    while (checked_int(&low) && checked_int(&high)) {
        if (low == 0 && high == 0) break;
        if (low < -5 || high > 5 || low > high) {
            printf("bounds\n");
            continue;
        }
        printf("sum=%.0f\n", square_range(low, high));
    }
    return 0;
}
int checked_int(int *target) {
    int status = scanf("%d", target);
    while (status != 1) {
        if (status == EOF) return 0;
        printf("invalid\n");
        int ch = getchar();
        while (ch != EOF && ch != '\n') ch = getchar();
        if (ch == EOF) return 0;
        status = scanf("%d", target);
    }
    return 1;
}
double square_range(int low, int high) {
    double sum = 0.0;
    for (int item = low; item <= high; item++) {
        sum += (double)item * item;
    }
    return sum;
}

#include <stdio.h>
#include <ctype.h>
int first_choice(void);
void discard_line(void);
int main(void) {
    int choice = first_choice();
    while (choice != EOF && choice != 'q') {
        switch (choice) {
            case 'a': printf("read carefully\n"); break;
            case 'c': {
                int count = 0;
                int status = scanf("%d", &count);
                while (status == 0) {
                    printf("invalid-number\n");
                    discard_line();
                    status = scanf("%d", &count);
                }
                if (status == EOF) return 0;
                discard_line();
                if (count < 0 || count > 5) {
                    printf("bounds\n");
                } else {
                    for (int i = 1; i <= count; i++) printf("%d\n", i);
                }
                break;
            }
            default: printf("invalid-choice\n"); break;
        }
        choice = first_choice();
    }
    return 0;
}
void discard_line(void) {
    int ch = getchar();
    while (ch != EOF && ch != '\n') ch = getchar();
}
int first_choice(void) {
    int ch = getchar();
    while (ch != EOF && isspace(ch)) ch = getchar();
    if (ch == EOF) return EOF;
    discard_line();
    return ch;
}

